def most_repeated_letters(text):
    """
    Returns a dictionary with the count of each lowercase letter in the input string.
    Spaces are ignored.
    """
    counts = {}
    for ch in text:
        if ch != ' ':
            counts[ch] = counts.get(ch, 0) + 1
    return counts
```

