def product_of_signs(numbers):
    if not numbers:
        return None
    sign_product = 1
    absolute_sum = 0
    for num in numbers:
        if num > 0:
            sign_product *= 1
        elif num < 0:
            sign_product *= -1
        else:
            sign_product = 0
        absolute_sum += abs(num)
    return absolute_sum + sign_product
