def nth_sequence_number(n):
    if n <= 0:
        return None
    if n == 1 or n == 2:
        return 0
    if n == 3:
        return 1
    a, b, c = 0, 0, 1
    for _ in range(4, n + 1):
        a, b, c = b, c, a + b + c
    return c
