def smallest_diff_at_least(arr, min_value):
    if len(arr) < 2:
        return None
    arr_sorted = sorted(arr)
    smallest = float('inf')
    for i in range(len(arr_sorted) - 1):
        diff = abs(arr_sorted[i+1] - arr_sorted[i])
        if diff >= min_value and diff < smallest:
            smallest = diff
    return smallest if smallest != float('inf') else None
